int countLeadingZeros_1(u32 x) {
int ans = 0;
if (x >> 16) x >>= 16; else ans |= 16;
if (x >> 8) x >>= 8; else ans |= 8;
if (x >> 4) x >>= 4; else ans |= 4;
if (x >> 2) x >>= 2; else ans |= 2;
if (x >> 1) x >>= 1; else ans |= 1;
return ans + !x;;
}
