int countTrailingZeros_1(u32 x) {
int ans = 0;
if (!(x & 65535u)) x >>= 16, ans |= 16;
if (!(x & 255u )) x >>= 8, ans |= 8;
if (!(x & 15u )) x >>= 4, ans |= 4;
if (!(x & 3u )) x >>= 2, ans |= 2;
if (!(x & 1u )) x >>= 1, ans |= 1;
return ans + !x;
}
