int kthBit_1(u32 x, int k) {
int ans = 0;
if (cnt_tbl[x & 65535u] < k)
k -= cnt_tbl[x & 65535u], ans |=16, x >>=16;
if (cnt_tbl[x & 255u ] < k)
k -= cnt_tbl[x & 255u ], ans |= 8, x >>= 8;
if (cnt_tbl[x & 15u ] < k)
k -= cnt_tbl[x & 15u ], ans |= 4, x >>= 4;
if (cnt_tbl[x & 3u ] < k)
k -= cnt_tbl[x & 3u ], ans |= 2, x >>= 2;
if (cnt_tbl[x & 1u ] < k)
k -= cnt_tbl[x & 1u ], ans |= 1, x >>= 1;
return ans;
}
